variante_1.js:
document.addEventListener('DOMContentLoaded', () => {
  const scrollTopBtn = document.getElementById('sl-scroll-top-btn');
  const scrollThreshold = 300; // Pixels to scroll before button appears

  if (!scrollTopBtn) return;

  const toggleScrollTopButton = () => {
    if (window.scrollY > scrollThreshold) {
      scrollTopBtn.style.display = 'flex';
      scrollTopBtn.style.opacity = '1';
    } else {
      scrollTopBtn.style.opacity = '0';
      setTimeout(() => {
        if (window.scrollY <= scrollThreshold) {
          scrollTopBtn.style.display = 'none';
        }
      }, 300); // Match CSS transition duration
    }
  };

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  window.addEventListener('scroll', toggleScrollTopButton);
  scrollTopBtn.addEventListener('click', scrollToTop);

  // Initial check
  toggleScrollTopButton();
});

variante_2.css:
.sl-fab-speed-dial {
  position: fixed;
  bottom: 20px;
  right: 20px;
  z-index: 1050;
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
}

.sl-fab-main-btn {
  width: 56px;
  height: 56px;
  padding: 0;
  font-size: 1.5rem;
  color: var(--sl-text-main);
  background-color: var(--sl-primary);
  border: none;
  transition: background-color 0.3s ease, transform 0.3s ease;
}

.sl-fab-main-btn:hover {
  background-color: var(--sl-accent);
  transform: rotate(45deg);
}

.sl-fab-sub-actions {
  display: flex;
  flex-direction: column-reverse;
  align-items: center;
  margin-bottom: 10px;
  opacity: 0;
  transform: translateY(20px) scale(0.8);
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.sl-fab-speed-dial:hover .sl-fab-sub-actions {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

.sl-fab-sub-btn {
  width: 40px;
  height: 40px;
  padding: 0;
  font-size: 1rem;
  margin-bottom: 8px;
  background-color: var(--sl-card-bg);
  color: var(--sl-primary);
  border: 1px solid var(--sl-border);
  transition: background-color 0.2s ease, transform 0.2s ease;
}

.sl-fab-sub-btn:hover {
  background-color: var(--sl-primary);
  color: var(--sl-text-main);
  transform: scale(1.05);
}

.sl-fab-sub-actions .sl-fab-sub-btn:nth-child(1) {
  transition-delay: 0.1s;
}
.sl-fab-sub-actions .sl-fab-sub-btn:nth-child(2) {
  transition-delay: 0.05s;
}
.sl-fab-sub-actions .sl-fab-sub-btn:nth-child(3) {
  transition-delay: 0s;
}

