variante_3.js:
document.addEventListener('DOMContentLoaded', () => {
  const shareFabBtn = document.getElementById('sl-share-fab-btn');
  const sharePanel = document.getElementById('sl-share-panel');

  if (!shareFabBtn || !sharePanel) return;

  const toggleSharePanel = () => {
    sharePanel.classList.toggle('show');
  };

  shareFabBtn.addEventListener('click', toggleSharePanel);

  // Close panel if clicked outside
  document.addEventListener('click', (event) => {
    if (!shareFabBtn.contains(event.target) && !sharePanel.contains(event.target) && sharePanel.classList.contains('show')) {
      sharePanel.classList.remove('show');
    }
  });
});

variante_4.css:
.sl-reading-progress-fab {
  position: fixed;
  bottom: 20px;
  right: 20px;
  z-index: 1050;
  width: 60px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--sl-card-bg);
  border-radius: 50%;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  transition: opacity 0.3s ease, transform 0.3s ease;
  opacity: 0;
  transform: scale(0.8);
  visibility: hidden;
}

.sl-reading-progress-fab.show {
  opacity: 1;
  transform: scale(1);
  visibility: visible;
}

.sl-progress-ring-bg {
  stroke: var(--sl-border);
}

.sl-progress-ring-fg {
  transition: stroke-dashoffset 0.3s ease-out;
  stroke-linecap: round;
}

.sl-progress-top-btn {
  position: absolute;
  background: none;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--sl-text-main);
}

.sl-progress-top-btn:hover svg {
  fill: var(--sl-accent);
}

