document.addEventListener('DOMContentLoaded', () => {
  const progressFab = document.getElementById('sl-reading-progress-fab');
  const progressBar = progressFab ? progressFab.querySelector('.sl-progress-ring-fg') : null;
  const scrollTopBtn = progressFab ? progressFab.querySelector('.sl-progress-top-btn') : null;

  if (!progressFab || !progressBar || !scrollTopBtn) return;

  const radius = parseFloat(progressBar.getAttribute('r'));
  const circumference = 2 * Math.PI * radius;
  progressBar.style.strokeDasharray = `${circumference} ${circumference}`;
  progressBar.style.strokeDashoffset = circumference;

  const scrollThreshold = 300; // Pixels to scroll before FAB appears

  const updateProgressBar = () => {
    const docHeight = document.documentElement.scrollHeight - window.innerHeight;
    const scrollPos = window.scrollY;
    const progress = (scrollPos / docHeight) * 100;
    const offset = circumference - (progress / 100) * circumference;

    progressBar.style.strokeDashoffset = offset;

    if (scrollPos > scrollThreshold) {
      progressFab.classList.add('show');
    } else {
      progressFab.classList.remove('show');
    }
  };

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  window.addEventListener('scroll', updateProgressBar);
  scrollTopBtn.addEventListener('click', scrollToTop);

  // Initial check
  updateProgressBar();
});
